import{K as r,a as i,c as l,b as a,k as n,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 图片、题注、交叉引用与参考文献","description":"插入和定位图片，选择文字环绕，统一图表编号，使用交叉引用、脚注与引文，检查字段更新和可访问性。","frontmatter":{"title":"Word 图片、题注、交叉引用与参考文献","description":"插入和定位图片，选择文字环绕，统一图表编号，使用交叉引用、脚注与引文，检查字段更新和可访问性。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"插入和定位图片，选择文字环绕，统一图表编号，使用交叉引用、脚注与引文，检查字段更新和可访问性。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 表格制作与跨页排版","link":"/tools/office/word/tables"},"next":{"text":"Word 修订、批注、比较与定稿","link":"/tools/office/word/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 表格制作与跨页排版","link":"/tools/office/word/tables"},"next":{"text":"Word 修订、批注、比较与定稿","link":"/tools/office/word/review"}},"headers":[],"relativePath":"tools/office/word/images-references.md","filePath":"tools/office/word/images-references.md"}'),h={name:"tools/office/word/images-references.md"},g=Object.assign(h,{setup(d){const o={path:"/tools/office/word/images-references",app:"Word",title:"让插图编号与正文引用一起更新",steps:[{tab:"插入",command:"图片",setting:"来源：此设备；布局：嵌入型",anchor:"walkthrough-1"},{tab:"引用",command:"插入题注",setting:"标签：图；标题：月度处理流程",anchor:"walkthrough-2"},{tab:"引用",command:"交叉引用",setting:"类型：图；内容：标签和编号",anchor:"walkthrough-3"}]};return(f,e)=>{const t=r("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=a("h1",{id:"word-图片、题注、交叉引用与参考文献",tabindex:"-1"},[n("Word 图片、题注、交叉引用与参考文献 "),a("a",{class:"header-anchor",href:"#word-图片、题注、交叉引用与参考文献","aria-label":'Permalink to "Word 图片、题注、交叉引用与参考文献"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇在报告中插入一张流程图，并在正文引用其编号。图像应帮助理解内容，正文也要解释图所表达的关键结论，不能只写“见下图”而没有说明。",-1)),s(t,{guide:o}),e[2]||(e[2]=c('<h2 id="images" tabindex="-1">插入、裁剪和定位 <a class="header-anchor" href="#images" aria-label="Permalink to &quot;插入、裁剪和定位 {#images}&quot;">​</a></h2><ol><li>将光标放在希望插图的段落，选择“插入 → 图片”，使用有权使用的本地图片。</li><li>在“图片格式 → 大小”中设置宽度，保持纵横比；不要分别拖动上下左右边把图片拉伸变形。</li><li>用“裁剪”去掉无关区域。需要去除敏感信息时，应在副本中清除隐藏内容并检查最终输出，单纯裁剪不等于底层图像已被删除。</li><li>初学者优先使用“嵌入型”，图片像大字符一样参与正文排版，位置较容易预测。</li><li>需要文字绕图时再选择“四周型”等环绕方式，检查对象锚点以及“随文字移动/固定位置”等选项。</li></ol><p>浮动图片的锚点与段落关联。删除或移动该段落可能影响图片位置；编辑标记和对象锚点有助于排查。多个对象难以选中时使用选择窗格，避免在正文中反复拖动碰运气。</p><h2 id="quality" tabindex="-1">清晰度与文件大小 <a class="header-anchor" href="#quality" aria-label="Permalink to &quot;清晰度与文件大小 {#quality}&quot;">​</a></h2><p>照片可适当压缩；包含小字的截图要在实际输出尺寸下检查。整页截图缩成半页后文字可能无法阅读，宜裁出关键区域或重做为可编辑表格。矢量图适合线条和图示，但目标应用和导出流程是否支持仍需验证。</p><p>通过“图片格式 → 压缩图片”调整分辨率时，先保留原始文件和未压缩副本。若选择删除裁剪区域，之后无法在当前文件中恢复那些区域。压缩不是每次保存都要做的步骤，应围绕交付体积和可读性取舍。</p><h2 id="references" tabindex="-1">自动题注与交叉引用 <a class="header-anchor" href="#references" aria-label="Permalink to &quot;自动题注与交叉引用 {#references}&quot;">​</a></h2><p>选中图片，使用“引用 → 插入题注”，选择“图”标签并输入说明，例如“图 1 数据汇总流程”。在正文中选择“引用 → 交叉引用”，引用该图的标签和编号，也可以选择页码。这样在前面新增图片后，更新字段即可重新编号。</p><p>文字“图 1”直接输入不会自动变化。交叉引用显示“错误！未找到引用源”时，通常是原题注或书签被删除；应重新选定正确的引用目标，而不是手动覆盖错误结果。字段更新后还需检查题注是否与对应图片同页，避免读者把标题看错对象。</p><h2 id="citations" tabindex="-1">脚注、尾注与文献 <a class="header-anchor" href="#citations" aria-label="Permalink to &quot;脚注、尾注与文献 {#citations}&quot;">​</a></h2><p>短解释可用脚注：将光标放在需要说明的词后，通过“引用 → 插入脚注”输入内容。尾注把说明集中到文档或节末尾。不要用上标数字加手打页底文字模拟脚注，否则增加内容后很难维护。</p><p>正式报告引用外部材料时，在“引用”中选择所需引文样式，添加来源信息，再插入引文和书目。作者、标题、年份等元数据必须核实；软件生成的格式仍应按单位要求检查，不能把自动排版当成来源准确性的证明。</p><h2 id="practice" tabindex="-1">可访问性与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;可访问性与验收 {#practice}&quot;">​</a></h2><p>为有信息含义的图片添加替代文字，说明它表达什么，例如“数据先校验，再按部门汇总，最后生成月报”。纯装饰图可按应用提供的选项标记为装饰。通过“审阅 → 检查辅助功能”检查可发现的问题，并人工确认阅读顺序和颜色对比。</p><p>练习：插入两张图和题注，正文分别交叉引用。再在第一张图前插入新图，更新字段；原来第二张图的编号和引用应一起变化。导出 PDF 后检查图片清晰度、图号、脚注位置和链接。</p><p>参考入口：<a href="https://support.microsoft.com/en-us/word/" target="_blank" rel="noopener noreferrer">Word 帮助与学习</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：让插图编号与正文引用一起更新 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：让插图编号与正文引用一起更新 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先让图片位置稳定 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先让图片位置稳定 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 图片。</strong></p><p>把光标放在说明段落之后，选择“插入 → 图片 → 此设备”，插入自己的练习图。先用嵌入型布局，让图片像大字符一样随段落移动；需要文字环绕时再调整。裁剪仅改变可见区域，不能自动消除文件中所有原始敏感信息。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：建立自动题注 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：建立自动题注 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：引用 → 插入题注。</strong></p><p>选中图片，点击“引用 → 插入题注”，标签选图，输入“月度处理流程”。Word 会生成编号；不要在前面再手写一个 1。插入第二张图并同样添加题注，观察编号递增，统一题注样式以免字号和间距各不相同。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：让正文引用跟随图号 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：让正文引用跟随图号 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：引用 → 交叉引用。</strong></p><p>在正文写“操作顺序见”，选择“引用 → 交叉引用”，引用类型选图，插入对应标签和编号。把两张图调换顺序后更新相关域，检查题注与引用同步变化。正文 Ctrl+A、F9 可更新主体中的域，页眉页脚或文本框中的域还应单独检查。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>出现“错误！未找到引用源”时，通常是目标被删除或对应书签失效。重新插入正确引用；把报错文字改成手写图号只能隐藏问题，不能恢复关联。</p>',29))])}}});export{u as __pageData,g as default};
